#include <iostream>
#include <string>

void solution(const std::string& str) {
    int count = 0;
    for (int i = 0; i < static_cast<int>(str.length()); ++i) {
        int j;
        for (j = i - 1; j >= 0; --j) {
            if (str[i] == str[j]) {
                break;
            }
        }
        if (j == -1) {
            count++;
        }
    }
    if (count % 2 != 0) {
        std::cout << "IGNORE HIM!" << std::endl;
    } else {
        std::cout << "CHAT WITH HER!" << std::endl;
    }
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    std::string str;
    std::getline(std::cin, str);

    solution(str);

    return 0;
}

